$ErrorActionPreference = 'Stop'

$Root = 'C:\code\_Scripts\Taskbar-Groups'
$Source = Join-Path $Root 'Taskbar-GroupMenu.cs'
$Build = Join-Path $Root 'Build-TaskbarGroupMenu.ps1'
$BackupDir = Join-Path $Root '_backups'

if (-not (Test-Path $Root)) { throw "Taskbar Groups root not found: $Root" }
if (-not (Test-Path $Build)) { throw "Build script not found: $Build" }
if (-not (Test-Path $BackupDir)) {
    New-Item -ItemType Directory -Path $BackupDir | Out-Null
}

if (Test-Path $Source) {
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $backup = Join-Path $BackupDir "Taskbar-GroupMenu-$stamp.cs"
    Copy-Item -LiteralPath $Source -Destination $backup
    Write-Host "Backed up current source to:"
    Write-Host "  $backup"
    Write-Host
}

[IO.File]::WriteAllBytes($Source, [Convert]::FromBase64String(''))

Write-Host "Updated canonical source:"
Write-Host "  $Source"
Write-Host
Write-Host "Building..."
Write-Host

& $Build
if ($LASTEXITCODE -ne 0) { throw "Compilation failed." }

Write-Host
Write-Host "Taskbar Group Menu updated successfully."
